import{Z as e,e as a,f as n,a0 as s}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Snaptcha","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/captchas/snaptcha.md","filePath":"integrations/captchas/snaptcha.md","lastUpdated":1781527112000}'),o={name:"integrations/captchas/snaptcha.md"};function i(r,t,h,l,c,p){return a(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="snaptcha" tabindex="-1">Snaptcha <a class="header-anchor" href="#snaptcha" aria-label="Permalink to &quot;Snaptcha&quot;">​</a></h1><p>Follow the below steps to use Snaptcha with Formie.</p><h3 id="step-1-install-and-configure-snaptcha" tabindex="-1">Step 1. Install and Configure Snaptcha <a class="header-anchor" href="#step-1-install-and-configure-snaptcha" aria-label="Permalink to &quot;Step 1. Install and Configure Snaptcha&quot;">​</a></h3><ol><li>Install the <a href="https://plugins.craftcms.com/snaptcha" target="_blank" rel="noreferrer">Snaptcha plugin</a> for Craft CMS.</li><li>Configure Snaptcha itself using that plugin&#39;s settings and setup instructions.</li></ol><h3 id="step-2-open-the-captcha-settings" tabindex="-1">Step 2. Open the Captcha Settings <a class="header-anchor" href="#step-2-open-the-captcha-settings" aria-label="Permalink to &quot;Step 2. Open the Captcha Settings&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Spam Protection</strong> → <strong>Captchas</strong>.</li><li>Select <strong>Snaptcha</strong> in the left-hand sidebar.</li><li>Turn on <strong>Enabled</strong>.</li><li>Save the captcha settings.</li></ol><h3 id="step-3-form-setting" tabindex="-1">Step 3. Form Setting <a class="header-anchor" href="#step-3-form-setting" aria-label="Permalink to &quot;Step 3. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to protect.</li><li>Enable <strong>Snaptcha</strong> for that form.</li><li>For multi-page forms, turn on <strong>Show on All Pages</strong> if Snaptcha should run on every page instead of only the final submit step.</li><li>Save the form.</li></ol><p>Formie reads the Snaptcha field name and token value from the Snaptcha plugin, so there are no extra keys to enter in Formie itself.</p><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Submit through the site and check the resulting submission and spam state. A saved credential alone does not verify the visitor-facing challenge or server-side check.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',12)])])}const f=e(o,[["render",i]]);export{g as __pageData,f as default};
